source:
source note sys.dataset(fields: [title, subtitle, status, summary, as_of, metric1_label, metric1_value, pick1_title, pick1_body, pick2_title, pick2_body])

copy app { class: vocabulary, en: "Mail" }
copy sim { class: vocabulary, en: "OctoSense simulation" }
copy b_show_code { class: vocabulary, en: "Show code" }
copy b_details { class: vocabulary, en: "Details" }
copy b_back { class: vocabulary, en: "Back" }
copy gist { class: model-copy, en: "No redelivery was arranged, so collect in person - bring the code and photo ID." }

state mode { shape: enum[brief, code, details], initial: .brief }
event show_code { mode: set(.code) }
event show_details { mode: set(.details) }
event back { mode: set(.brief) }

view root Surface(pad: .tight) {
  Col(gap: 8) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.sim, width: .fill)
      TextCaption(value: note.as_of)
    }
    TextTitle(text: note.title, width: .fill)
    TextCaption(text: note.subtitle, width: .fill)
    TextCaption(text: note.status)
    when mode == .brief {
      Col(gap: 8) {
        TextBody(text: note.summary, width: .fill)
        Row(gap: 8, align: .center) {
          TextCaption(text: note.metric1_label)
          TextBody(text: note.metric1_value, width: .fill)
        }
        TextBody(text: copy.gist, width: .fill)
        Col(gap: 8) {
          Chip(text: copy.b_show_code, on_tap: show_code, tone: .primary)
          Chip(text: copy.b_details, on_tap: show_details)
        }
      }
    }
    when mode == .code {
      Col(gap: 8) {
        TextBody(text: note.pick1_title, width: .fill)
        TextBody(text: note.pick1_body, width: .fill)
        Chip(text: copy.b_back, on_tap: back, tone: .primary)
      }
    }
    when mode == .details {
      Col(gap: 8) {
        TextBody(text: note.pick2_title, width: .fill)
        TextBody(text: note.pick2_body, width: .fill)
        Row(gap: 8, align: .center) {
          TextCaption(text: note.metric1_label)
          TextBody(text: note.metric1_value, width: .fill)
        }
        Chip(text: copy.b_back, on_tap: back, tone: .primary)
      }
    }
  }
}
